import React, { useState } from 'react';
import { CareRole, User, AppTab } from './types';
import Sidebar from './components/Sidebar';
import Login from './features/Login';
import Dashboard from './features/Dashboard';
import { Search, Bell, Settings, UserCircle } from 'lucide-react';
import { MOCK_CLIENTS } from './data/careData';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [language, setLanguage] = useState<string>('English');

  if (!user) return <Login onLogin={setUser} language={language} onLanguageChange={setLanguage} />;

  const renderContent = () => {
    switch (activeTab) {
      case AppTab.DASHBOARD: return <Dashboard staffName={user.name} clients={MOCK_CLIENTS} language={language} />;
      default: return (
        <div className="h-full flex items-center justify-center opacity-30 italic">
          <p className="text-xl uppercase tracking-widest font-black">Vector_{activeTab.replace(' ', '_')}_Locked</p>
        </div>
      );
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#020617] text-slate-200 overflow-hidden select-none">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        role={user.role} 
        onLogout={() => setUser(null)}
      />

      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="h-20 border-b border-white/5 flex items-center justify-between px-10 backdrop-blur-xl">
          <div className="flex flex-col">
            <p className="text-[8px] font-black text-indigo-500 uppercase tracking-[0.4em] mb-0.5">Active Protocol</p>
            <h2 className="text-sm font-black text-white uppercase italic tracking-widest">{activeTab}</h2>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden lg:flex items-center gap-3 bg-white/5 border border-white/10 px-5 py-2 rounded-2xl group focus-within:border-indigo-500/50 transition-all">
              <Search size={16} className="text-slate-500 group-focus-within:text-indigo-400" />
              <input type="text" placeholder="..." className="bg-transparent border-none text-xs text-slate-200 outline-none w-48 font-medium" />
            </div>

            <div className="flex items-center gap-2">
              <button className="p-2.5 text-slate-400 hover:text-white transition-all"><Bell size={18} /></button>
              <button className="p-2.5 text-slate-400 hover:text-white transition-all"><Settings size={18} /></button>
            </div>

            <div className="flex items-center gap-4 pl-4 border-l border-white/5">
              <div className="text-right hidden sm:block">
                <p className="text-[10px] font-black text-white uppercase italic leading-none">{user.name}</p>
                <p className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-1">{user.role}</p>
              </div>
              <div className="w-10 h-10 rounded-2xl bg-indigo-600/20 flex items-center justify-center text-indigo-400 border border-indigo-500/20">
                <UserCircle size={22} />
              </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto scrollbar-hide p-10">
          <div className="max-w-[1400px] mx-auto h-full">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { AppTab, CareRole } from '../types';
import { 
  LayoutDashboard, 
  ShieldAlert, 
  Users, 
  Briefcase, 
  Wallet, 
  Database, 
  Radio,
  Power
} from 'lucide-react';

interface Props {
  activeTab: AppTab;
  setActiveTab: (tab: AppTab) => void;
  role: CareRole;
  onLogout: () => void;
  language?: string;
}

const Sidebar: React.FC<Props> = ({ activeTab, setActiveTab, role, onLogout, language }) => {
  const menu = [
    { id: AppTab.DASHBOARD, icon: LayoutDashboard, label: 'Ops Dashboard' },
    { id: AppTab.CLINICAL, icon: ShieldAlert, label: 'Clinical Core' },
    { id: AppTab.LOGISTICS, icon: Users, label: 'Dispatch Grid' },
    { id: AppTab.RESOURCE, icon: Briefcase, label: 'Resource Core' },
    { id: AppTab.FISCAL, icon: Wallet, label: 'Fiscal Ledger' },
    { id: AppTab.VAULT, icon: Database, label: 'Neural Vault' },
    { id: AppTab.LIVE, icon: Radio, label: 'Direct Link' },
  ];

  return (
    <aside className="w-64 bg-black/40 border-r border-white/5 flex flex-col h-full backdrop-blur-xl">
      <div className="h-20 flex items-center px-8 border-b border-white/5">
        <span className="text-xl font-black text-white italic tracking-tighter">CARESYNC<span className="text-indigo-500">PRO</span></span>
      </div>

      <nav className="flex-1 p-4 space-y-2 overflow-y-auto scrollbar-hide">
        {menu.map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all ${
              activeTab === item.id 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                : 'text-slate-500 hover:text-slate-200 hover:bg-white/5'
            }`}
          >
            <item.icon size={18} />
            <span className="text-[10px] font-bold uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="p-4 border-t border-white/5">
        <button 
          onClick={onLogout}
          className="w-full flex items-center gap-4 px-4 py-3 rounded-xl text-rose-500 hover:bg-rose-500/10 transition-all"
        >
          <Power size={18} />
          <span className="text-[10px] font-bold uppercase tracking-widest">Terminate Session</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { ethicsAdvisoryService } from '../../services/ethicsAdvisoryService';
import { Client, EthicsConsult } from '../../types';
import Translate from '../../components/Translate';

interface Props {
  language: string;
  clients: Client[];
}

const EthicsAdvisoryBoard: React.FC<Props> = ({ language, clients }) => {
  const [selectedClientId, setSelectedClientId] = useState(clients[0]?.id || '');
  const [dilemma, setDilemma] = useState("");
  const [consult, setConsult] = useState<EthicsConsult | null>(null);
  const [loading, setLoading] = useState(false);

  const runConsult = async () => {
    if (!dilemma.trim()) return;
    setLoading(true);
    const client = clients.find(c => c.id === selectedClientId);
    if (!client) return;

    try {
      const result = await ethicsAdvisoryService.consultEthics(client, dilemma);
      setConsult(result);
    } catch (e) {
      alert("Moral Logic Desync. Re-aligning framework...");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="h-full space-y-12 animate-in fade-in duration-1000 pb-24">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-slate-400">Ethics_Advisory_Board</h2>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-2">Dilemma Arbitration & Moral Liability Protection</p>
        </div>
        <div className="flex bg-white/5 p-1 rounded-2xl border border-white/10">
           {clients.slice(0, 3).map(c => (
             <button 
              key={c.id}
              onClick={() => setSelectedClientId(c.id)}
              className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedClientId === c.id ? 'bg-slate-700 text-white' : 'text-slate-500 hover:text-white'}`}
             >
               {c.name}
             </button>
           ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Input & Perspectives */}
        <div className="lg:col-span-8 bg-[#0a0c10] border border-white/5 rounded-[4rem] p-12 shadow-2xl relative overflow-hidden flex flex-col min-h-[700px]">
           <div className="absolute inset-0 opacity-[0.02] pointer-events-none bg-[url('https://grainy-gradients.vercel.app/noise.svg')] bg-repeat"></div>

           <div className="space-y-10 relative z-10">
              <section>
                 <h3 className="text-xs font-black text-slate-600 uppercase tracking-widest mb-6 italic">Ingest_Clinical_Dilemma</h3>
                 <textarea 
                  value={dilemma}
                  onChange={(e) => setDilemma(e.target.value)}
                  placeholder="E.g. Patient with dementia refuses to utilize Hoyer lift, creating extreme caregiver strain and skin risk. Family demands no mechanical force."
                  className="w-full h-40 p-8 bg-white/[0.02] border border-white/5 rounded-[3rem] text-sm text-slate-300 italic leading-relaxed focus:outline-none focus:border-white/20 transition-all scrollbar-hide"
                 />
                 <button 
                  onClick={runConsult}
                  disabled={loading || !dilemma.trim()}
                  className="w-full mt-8 py-6 bg-white text-black rounded-3xl font-black text-xs uppercase tracking-[0.4em] shadow-xl hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-30"
                 >
                   {loading ? 'WEIGHING_MORAL_VECTORS...' : 'INITIATE_ETHICAL_CONSULT'}
                 </button>
              </section>

              {consult && !loading && (
                <section className="animate-in slide-in-from-bottom-8 duration-700 space-y-12 pt-10 border-t border-white/5">
                   <div>
                      <p className="text-[9px] font-black text-rose-500 uppercase tracking-widest mb-6">Identified_Moral_Conflict</p>
                      <p className="text-3xl font-bold text-white leading-tight italic uppercase tracking-tighter">"{consult.moralConflict}"</p>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      {consult.stakeholderPerspectives.map((p: any, i: number) => (
                        <div key={i} className="p-6 bg-white/[0.02] border border-white/5 rounded-3xl">
                           <p className="text-[8px] font-black text-slate-500 uppercase mb-3">{p.entity}</p>
                           <p className="text-[11px] text-slate-200 font-bold mb-3 italic">"{p.focus}"</p>
                           <p className="text-[9px] font-black text-rose-500 uppercase">Risk: {p.risk}</p>
                        </div>
                      ))}
                   </div>
                </section>
              )}
           </div>
        </div>

        {/* The Directive Sidebar */}
        <div className="lg:col-span-4 space-y-6 flex flex-col">
           <div className="bg-[#1e293b] p-12 rounded-[3rem] text-white shadow-2xl relative overflow-hidden flex flex-col group">
              <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none">
