    } catch (e) {
      return {
        id: 'error-mandate',
        companyId: 'csp-demo',
        createdAt: new Date().toISOString(),
        timestamp: new Date().toISOString(),
        stateOfAgency: "Synthesis failed.",
        institutionalFragilityPoints: [],
